<script setup lang="ts">
import {onUnmounted,ref} from 'vue'
import {request,isCancelled,ApiError} from '../../shared/api/client'
import {parseTelphinCredentials} from '../../shared/interfaces/assistant'
import type {CredentialSummary,TelphinCredentials} from '../../shared/interfaces/assistant'
import {useAssistant} from '../../entities/assistant/model'
import Icon from '../../shared/ui/Icon.vue'
const emit=defineEmits<{close:[];saved:[CredentialSummary]}>(),store=useAssistant(),mode=ref<'fields'|'json'>('fields'),appId=ref(''),appSecret=ref(''),clientId=ref(''),host=ref<TelphinCredentials['host']>('apiproxy.telphin.ru'),json=ref(''),label=ref('Доступы Телфина'),error=ref(''),saving=ref(false),controller=new AbortController()
function clear(){appId.value='';appSecret.value='';clientId.value='';json.value=''}
function close(){controller.abort();clear();emit('close')}
onUnmounted(()=>{controller.abort();clear()})
async function save(){error.value='';let config:TelphinCredentials;try{config=mode.value==='json'?parseTelphinCredentials(json.value):parseTelphinCredentials(JSON.stringify({host:host.value,app_id:appId.value,app_secret:appSecret.value,client_id:clientId.value}))}catch(e){error.value=e instanceof Error?e.message:'Проверьте поля доступов';return}saving.value=true;try{const thread=await store.createConversation();if(controller.signal.aborted)return;const result=await request<CredentialSummary>('/assistant/conversations/'+thread.id+'/credentials',{method:'POST',body:{kind:'telphin',label:label.value.trim()||'Доступы Телфина',config},signal:controller.signal});if(controller.signal.aborted)return;clear();emit('saved',result)}catch(e){if(!isCancelled(e))error.value=({telphin_identity_auth_failed:'Телфин не принял App ID и App Secret. Проверьте данные приложения.',telphin_identity_scope_required:'Нужен API-доступ ко всей АТС, а не к отдельному добавочному номеру.',telphin_identity_timeout:'Телфин не ответил вовремя. Повторите сохранение.',telphin_identity_unavailable:'Не удалось определить ID АТС через Телфин. Повторите попытку.',telphin_identity_invalid:'Телфин не вернул ID АТС. Проверьте доступ приложения.'} as Record<string,string>)[e instanceof ApiError?e.code:'']||'Не удалось сохранить доступы. Проверьте данные и соединение с сервером.'}finally{config={app_id:'',app_secret:'',client_id:''};saving.value=false}}
</script>
<template><section class="assistant-secure" aria-label="Защищённая форма доступов Телфина"><div class="assistant-secure-heading"><span><Icon name="lock" :size="17"/>Доступы Телфина</span><button class="icon-button" aria-label="Закрыть форму доступов" @click="close"><Icon name="close" :size="16"/></button></div><p>Достаточно App ID и App Secret: Client ID определится автоматически. Доступы сохраняются отдельно от переписки.</p><div class="assistant-form-tabs"><button type="button" :class="{active:mode==='fields'}" @click="mode='fields'">Заполнить поля</button><button type="button" :class="{active:mode==='json'}" @click="mode='json'">Вставить JSON</button></div><form @submit.prevent="save" autocomplete="off"><label>Название доступа<input v-model="label" maxlength="80" autocomplete="off"/></label><template v-if="mode==='fields'"><label>Сервер Телфина<select v-model="host"><option>apiproxy.telphin.ru</option><option>altapi.telphin.ru</option></select></label><div class="assistant-fields"><label>App ID<input v-model="appId" required autocomplete="off"/></label><label>Client ID · необязательно<input v-model="clientId" placeholder="Определим автоматически" autocomplete="off" inputmode="numeric" pattern="[0-9]{1,40}" maxlength="40"/></label></div><label>App Secret<input v-model="appSecret" type="password" required autocomplete="new-password"/></label></template><label v-else>JSON доступов<textarea v-model="json" class="assistant-secret-json" rows="5" required spellcheck="false" autocomplete="off" placeholder='{"app_id":"…","app_secret":"…"}'></textarea></label><p v-if="error" class="assistant-error" role="alert">{{error}}</p><div class="assistant-form-actions"><button class="button small" type="button" @click="close">Отмена</button><button class="button primary small" :disabled="saving">{{saving?'Сохраняем…':'Сохранить доступы'}}</button></div></form></section></template>
